SELECT sources.* FROM  (SELECT a.namespace,a.client_id,a.origin,a.profile_channel,a.browser_instance,a.tab_id,a.document_id,a.document_generation,a.chrome_start_token,a.broker_epoch,a.channel_epoch,a.scope_hash,a.selection_id AS preparation_id FROM credential_delivery_attempts a JOIN credential_delivery_preparations p ON p.namespace=a.namespace AND p.client_id=a.client_id AND p.preparation_id=a.selection_id WHERE a.namespace=:Namespace AND a.client_id=:ClientID AND a.origin=:Origin AND p.protection_state='held' AND p.revision=1 AND a.session_id=p.session_id AND a.grant_id=p.grant_id AND a.purpose_hash=p.purpose_hash AND a.selected_revision=p.selected_revision AND a.origin=p.origin AND a.attempt_id=(SELECT MIN(z.attempt_id) FROM credential_delivery_attempts z WHERE z.namespace=a.namespace AND z.client_id=a.client_id AND z.selection_id=a.selection_id) AND NOT EXISTS(SELECT 1 FROM credential_delivery_attempts x WHERE x.namespace=a.namespace AND x.client_id=a.client_id AND x.selection_id=a.selection_id AND (x.profile_channel<>a.profile_channel OR x.browser_instance<>a.browser_instance OR x.tab_id<>a.tab_id OR x.document_id<>a.document_id OR x.chrome_start_token<>a.chrome_start_token OR x.session_id<>p.session_id OR x.grant_id<>p.grant_id OR x.purpose_hash<>p.purpose_hash OR x.selected_revision<>p.selected_revision OR x.origin<>p.origin OR x.purpose_hash IS NULL OR x.document_generation<1 OR x.tab_id<1 OR x.chrome_start_token='' OR x.document_id='')) ORDER BY a.selection_id LIMIT 513
)  sources